class Solution {public:long long solve(vector<vector<int>> grid){int m=grid.size(),n=m?grid[0].size():0;if(!n)return 0;vector<vector<long long>>d(n,vector<long long>(n,-1));d[0][n-1]=1LL*grid[0][0]+(n>1?grid[0][n-1]:0);for(int r=1;r<m;r++){vector<vector<long long>>next(n,vector<long long>(n,-1));for(int a=0;a<n;a++)for(int b=0;b<n;b++)if(d[a][b]>=0)for(int da=-1;da<=1;da++)for(int db=-1;db<=1;db++){int x=a+da,y=b+db;if(x>=0&&x<n&&y>=0&&y<n)next[x][y]=max(next[x][y],d[a][b]+grid[r][x]+(x==y?0:grid[r][y]));}d=next;}long long best=0;for(auto& row:d)for(auto value:row)best=max(best,value);return best;}};